import * as React from "react";
import { ContextMenu as ContextMenuPrimitive } from "radix-ui";

import { useV4CollisionBoundary, useV4PortalContainer } from "../scope";

import { ListHighlight } from "../lib/list-highlight";
import { MenuKindContext } from "../lib/menu-kind";
import { cn } from "../lib/utils";
import { Icon } from "./icon";
import { menuRowContent, menuShortcutContent } from "./menu-content";
import { useMenuInset } from "./menu-inset";

import menu from "./menu.module.css";

/**
 * Whether a pointer has pressed inside the open menu. Radix selects the item under a pointerup that
 * had no pointerdown on it, so the release of the opening right-click or long press would select
 * whichever item the menu placed under the cursor. Items take pointer releases only after a press.
 */
const PressedSinceOpenContext = React.createContext<React.RefObject<boolean> | null>(null);

function ContextMenu({ ...props }: React.ComponentProps<typeof ContextMenuPrimitive.Root>) {
  const pressedSinceOpen = React.useRef(false);
  return (
    <PressedSinceOpenContext value={pressedSinceOpen}>
      <ContextMenuPrimitive.Root data-slot="context-menu" {...props} />
    </PressedSinceOpenContext>
  );
}

function ContextMenuTrigger({
  className,
  disabled,
  onKeyDown,
  onContextMenuCapture,
  ref,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Trigger>) {
  const pressedSinceOpen = React.useContext(PressedSinceOpenContext);
  return (
    <ContextMenuPrimitive.Trigger
      ref={ref}
      data-slot="context-menu-trigger"
      className={cn("select-none", className)}
      disabled={disabled}
      {...props}
      onContextMenuCapture={(event) => {
        onContextMenuCapture?.(event);
        if (pressedSinceOpen) pressedSinceOpen.current = false;
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || disabled || event.repeat) return;
        if (event.key !== "ContextMenu" && !(event.shiftKey && event.key === "F10")) return;
        event.preventDefault();
        const rect = event.currentTarget.getBoundingClientRect();
        event.currentTarget.dispatchEvent(
          new MouseEvent("contextmenu", {
            bubbles: true,
            cancelable: true,
            clientX: rect.left + rect.width / 2,
            clientY: rect.top + rect.height / 2
          })
        );
      }}
    />
  );
}
ContextMenuTrigger.displayName = "ContextMenuTrigger";

function ContextMenuGroup({
  ref,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Group>) {
  return <ContextMenuPrimitive.Group ref={ref} data-slot="context-menu-group" {...props} />;
}
ContextMenuGroup.displayName = "ContextMenuGroup";

function ContextMenuPortal({ ...props }: React.ComponentProps<typeof ContextMenuPrimitive.Portal>) {
  return (
    <ContextMenuPrimitive.Portal
      container={useV4PortalContainer()}
      data-slot="context-menu-portal"
      {...props}
    />
  );
}

function ContextMenuSub({ ...props }: React.ComponentProps<typeof ContextMenuPrimitive.Sub>) {
  return <ContextMenuPrimitive.Sub data-slot="context-menu-sub" {...props} />;
}

function ContextMenuRadioGroup({
  ref,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.RadioGroup>) {
  return (
    <ContextMenuPrimitive.RadioGroup ref={ref} data-slot="context-menu-radio-group" {...props} />
  );
}
ContextMenuRadioGroup.displayName = "ContextMenuRadioGroup";

function ContextMenuContent({
  className,
  children,
  collisionPadding = 8,
  onPointerDownCapture,
  onPointerUpCapture,
  ref,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Content>) {
  const pressedSinceOpen = React.useContext(PressedSinceOpenContext);
  const insetRef = useMenuInset(ref);
  return (
    <ContextMenuPrimitive.Portal container={useV4PortalContainer()}>
      <ContextMenuPrimitive.Content
        ref={insetRef}
        data-slot="context-menu-content"
        collisionPadding={collisionPadding}
        collisionBoundary={useV4CollisionBoundary()}
        className={cn("z-50", menu.surface, menu.panel, menu.inset, menu.motion, className)}
        data-scroll-fade="y"
        {...props}
        onPointerDownCapture={(event) => {
          onPointerDownCapture?.(event);
          if (pressedSinceOpen) pressedSinceOpen.current = true;
        }}
        onPointerUpCapture={(event) => {
          onPointerUpCapture?.(event);
          if (pressedSinceOpen && !pressedSinceOpen.current) event.preventDefault();
        }}
      >
        <MenuKindContext value="context">{children}</MenuKindContext>
        <ListHighlight />
      </ContextMenuPrimitive.Content>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuContent.displayName = "ContextMenuContent";

function ContextMenuItem({
  className,
  inset,
  variant = "default",
  children,
  description,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof ContextMenuPrimitive.Item> & {
  description?: React.ReactNode;
  inset?: boolean;
  variant?: "default" | "destructive";
} & { ref?: React.Ref<React.ComponentRef<typeof ContextMenuPrimitive.Item>> }) {
  return (
    <ContextMenuPrimitive.Item
      ref={ref}
      data-slot="context-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(menu.row, className)}
      {...props}
    >
      {menuRowContent(children, description)}
    </ContextMenuPrimitive.Item>
  );
}
ContextMenuItem.displayName = "ContextMenuItem";

function ContextMenuSubTrigger({
  className,
  inset,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof ContextMenuPrimitive.SubTrigger> & {
  inset?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof ContextMenuPrimitive.SubTrigger>> }) {
  return (
    <ContextMenuPrimitive.SubTrigger
      ref={ref}
      data-slot="context-menu-sub-trigger"
      data-inset={inset}
      className={cn(menu.row, className)}
      {...props}
    >
      {menuRowContent(children)}
      <Icon name="chev-right" className={menu.trail} />
    </ContextMenuPrimitive.SubTrigger>
  );
}
ContextMenuSubTrigger.displayName = "ContextMenuSubTrigger";

function ContextMenuSubContent({
  className,
  children,
  collisionPadding = 8,
  sideOffset = 4,
  alignOffset = -3,
  ref,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.SubContent>) {
  const insetRef = useMenuInset(ref);
  return (
    <ContextMenuPrimitive.Portal container={useV4PortalContainer()}>
      <ContextMenuPrimitive.SubContent
        ref={insetRef}
        data-slot="context-menu-sub-content"
        collisionPadding={collisionPadding}
        collisionBoundary={useV4CollisionBoundary()}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        className={cn(
          "z-50",
          menu.surface,
          menu.panel,
          menu.sub,
          menu.inset,
          menu.motion,
          className
        )}
        data-scroll-fade="y"
        {...props}
      >
        <MenuKindContext value="context">{children}</MenuKindContext>
        <ListHighlight />
      </ContextMenuPrimitive.SubContent>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuSubContent.displayName = "ContextMenuSubContent";

function ContextMenuCheckboxItem({
  className,
  children,
  description,
  checked,
  inset,
  onSelect,
  closeOnSelect = false,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof ContextMenuPrimitive.CheckboxItem> & {
  description?: React.ReactNode;
  closeOnSelect?: boolean;
} & {
  inset?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof ContextMenuPrimitive.CheckboxItem>> }) {
  return (
    <ContextMenuPrimitive.CheckboxItem
      ref={ref}
      data-slot="context-menu-checkbox-item"
      data-inset={inset}
      className={cn(menu.row, className)}
      checked={checked}
      {...props}
      onSelect={(event) => {
        onSelect?.(event);
        if (!closeOnSelect) event.preventDefault();
      }}
    >
      <span className={menu.indicator}>
        <ContextMenuPrimitive.ItemIndicator>
          <Icon name="check" />
        </ContextMenuPrimitive.ItemIndicator>
      </span>
      {menuRowContent(children, description)}
    </ContextMenuPrimitive.CheckboxItem>
  );
}
ContextMenuCheckboxItem.displayName = "ContextMenuCheckboxItem";

function ContextMenuRadioItem({
  className,
  children,
  description,
  inset,
  onSelect,
  closeOnSelect = false,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof ContextMenuPrimitive.RadioItem> & {
  description?: React.ReactNode;
  closeOnSelect?: boolean;
} & {
  inset?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof ContextMenuPrimitive.RadioItem>> }) {
  return (
    <ContextMenuPrimitive.RadioItem
      ref={ref}
      data-slot="context-menu-radio-item"
      data-inset={inset}
      className={cn(menu.row, className)}
      {...props}
      onSelect={(event) => {
        onSelect?.(event);
        if (!closeOnSelect) event.preventDefault();
      }}
    >
      <span className={menu.indicator}>
        <ContextMenuPrimitive.ItemIndicator>
          <Icon name="check" />
        </ContextMenuPrimitive.ItemIndicator>
      </span>
      {menuRowContent(children, description)}
    </ContextMenuPrimitive.RadioItem>
  );
}
ContextMenuRadioItem.displayName = "ContextMenuRadioItem";

function ContextMenuLabel({
  className,
  inset,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof ContextMenuPrimitive.Label> & {
  inset?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof ContextMenuPrimitive.Label>> }) {
  return (
    <ContextMenuPrimitive.Label
      ref={ref}
      data-slot="context-menu-label"
      data-inset={inset}
      className={cn(menu.label, className)}
      {...props}
    />
  );
}
ContextMenuLabel.displayName = "ContextMenuLabel";

function ContextMenuSeparator({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Separator>) {
  return (
    <ContextMenuPrimitive.Separator
      ref={ref}
      data-slot="context-menu-separator"
      className={cn(menu.separator, className)}
      {...props}
    />
  );
}
ContextMenuSeparator.displayName = "ContextMenuSeparator";

function ContextMenuShortcut({ className, children, ref, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      ref={ref}
      data-slot="context-menu-shortcut"
      className={cn(menu.shortcut, className)}
      {...props}
    >
      {menuShortcutContent(children)}
    </span>
  );
}
ContextMenuShortcut.displayName = "ContextMenuShortcut";

export {
  ContextMenu,
  ContextMenuCheckboxItem,
  ContextMenuContent,
  ContextMenuGroup,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuPortal,
  ContextMenuRadioGroup,
  ContextMenuRadioItem,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
  ContextMenuTrigger
};

import * as React from "react";

import { useDescendantFlags } from "../lib/descendant-flags";

import menu from "./menu.module.css";

const leadIcon = `:is(svg, [data-menu-icon]):not(.${menu.trail})`;
const insetFlags = {
  "data-icon-slot": `.${menu.row} > ${leadIcon}, .${menu.row}[data-inset], .${menu.label}[data-inset]`
};
const insetWatch = {
  attributes: ["data-inset"],
  marks: { "data-lead-icon": `.${menu.row}:has(> ${leadIcon})` }
};

/** The ref for a menu inset: it reserves the lead icon column once any row has an icon or is inset, and marks the rows that bring their own icon. */
export const useMenuInset = <T extends Element>(ref?: React.Ref<T>) =>
  useDescendantFlags<T>(insetFlags, insetWatch, ref);

.surface {
  box-sizing: border-box;
  border-radius: 0;
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
  white-space: normal;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.panel {
  min-width: min(
    max(var(--v4-size-menu-min), var(--radix-popper-anchor-width, 0px)),
    var(--radix-popper-available-width, 100vw)
  );
  max-width: min(
    var(--v4-size-menu-max),
    var(--radix-popper-available-width, calc(100vw - 2 * var(--v4-space-16)))
  );
  max-height: var(--radix-popper-available-height, none);
  overflow-x: hidden;
  overflow-y: auto;
}
.sub {
  min-width: var(--v4-size-menu-min);
}
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.card {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-8);
  width: min(var(--v4-size-popover), var(--radix-popper-available-width, 100vw));
  max-height: var(--radix-popper-available-height, none);
  overflow-y: auto;
  scroll-padding-block: var(--v4-focus-clearance);
  padding: var(--v4-space-12);
}
.card[data-width="sm"] {
  width: min(var(--v4-size-sheet-sm), var(--radix-popper-available-width, 100vw));
}
.card[data-width="md"] {
  width: min(var(--v4-size-sheet-md), var(--radix-popper-available-width, 100vw));
}
.card[data-width="content"] {
  width: max-content;
  max-width: min(var(--v4-size-dialog-wide), var(--radix-popper-available-width, 100vw));
}
.tooltip {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-8);
  width: fit-content;
  max-width: min(var(--v4-size-tooltip-max), var(--radix-popper-available-width, 100vw));
  padding: var(--v4-space-6) var(--v4-space-8);
  pointer-events: none;
  user-select: none;
  white-space: normal;
  border-radius: 0;
  background-color: var(--v4-ink);
  color: var(--v4-on-ink);
  box-shadow: var(--v4-shadow-pop);
  overflow-wrap: break-word;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.tooltipText {
  min-width: 0;
}
.tooltip code {
  overflow-wrap: anywhere;
}
.tooltip[data-has-kbd] {
  padding-inline-end: var(--v4-space-6);
}
.tooltipArrow {
  fill: var(--v4-ink);
}

.motion {
  --v4-pop-from: 0 0;
  transform-origin: var(--radix-popper-transform-origin, center);
}
.motion[data-side="bottom"] {
  --v4-pop-from: 0 calc(-1 * var(--v4-space-4));
}
.motion[data-side="top"] {
  --v4-pop-from: 0 var(--v4-space-4);
}
.motion[data-side="right"] {
  --v4-pop-from: calc(-1 * var(--v4-space-4)) 0;
}
.motion[data-side="left"] {
  --v4-pop-from: var(--v4-space-4) 0;
}
.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation: popIn var(--v4-duration-fast) var(--v4-ease-spring) both;
}
.motion[data-state="closed"] {
  animation: popOut var(--v4-duration-exit-fast) var(--v4-ease-exit) both;
}
.tooltip.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation-name: tipIn;
}
.tooltip.motion[data-state="closed"] {
  animation-name: tipOut;
}
@keyframes popIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes popOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes tipIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes tipOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]),
  .tooltip.motion:is(
      [data-state="open"],
      [data-state="delayed-open"],
      [data-state="instant-open"]
    ) {
    animation-name: fadeIn;
  }
  .motion[data-state="closed"],
  .tooltip.motion[data-state="closed"] {
    animation-name: fadeOut;
  }
}

.inset,
.scroll {
  --v4-menu-pad: var(--v4-space-3);
}
.inset {
  --v4-menu-icon-slot: 0px;
  padding: var(--v4-menu-pad);
}
.inset[data-icon-slot] {
  --v4-menu-icon-slot: calc(var(--v4-size-icon) + var(--v4-space-8));
}

/* Nine whole rows plus one inset pad: at rest the top pad and nine rows show, and scrolled to the
   end the nine last rows and the bottom pad do, so neither edge ever cuts a row. */
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.list {
  max-height: calc(9 * var(--v4-size-control-sm) + var(--v4-menu-pad));
  overflow-x: hidden;
  overflow-y: auto;
  outline: none;
  scroll-padding-block: var(--v4-space-4);
}
.scroll {
  display: flex;
  flex-direction: column;
  min-height: 0;
  max-height: calc(9 * var(--v4-size-control-sm) + var(--v4-menu-pad));
}
.viewport {
  flex: 0 1 auto;
  min-height: 0;
  outline: none;
  scroll-padding-block: var(--v4-space-4);
}
.viewport > div {
  display: block !important;
}

.row {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  --v4-kbd-host-block: var(--v4-size-control-sm);
  --v4-kbd-host-end: var(--v4-space-8);
  border-radius: 0;
  overflow: hidden;
  color: var(--v4-ink);
  white-space: nowrap;
  cursor: default;
  user-select: none;
  outline: none;
  text-decoration: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.row.row[data-lead-icon] {
  padding-inline-start: var(--v4-space-8);
}
.row > svg,
.row > [data-menu-icon] {
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  pointer-events: none;
}
:global(.v4) {
  --overlay-hover: var(--v4-hover-mix);
}
.row:is(
    [data-highlighted],
    [data-selected="true"],
    [data-active],
    [data-state="open"],
    a:hover,
    a:focus-visible
  ) {
  background-color: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-hover), transparent);
}
.row:is([data-variant="destructive"], [data-danger]) {
  color: var(--v4-bad);
}
.row:is([data-variant="destructive"], [data-danger]):is(
    [data-highlighted],
    [data-selected="true"]
  ) {
  background-color: var(--v4-action-danger-surface);
}
.row:is([data-disabled]:not([data-disabled="false"]), [aria-disabled="true"]) {
  color: var(--v4-faint);
  background-color: transparent;
  pointer-events: none;
}
.indicator {
  order: 1;
  display: flex;
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  align-items: center;
  justify-content: center;
  margin-inline-start: auto;
  pointer-events: none;
}
.indicator > svg {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.indicator ~ :is(.shortcut, .meta) {
  margin-inline-start: 0;
}
.row:not([data-checked="true"]) > .indicator[data-command] {
  visibility: hidden;
}
.text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}
.title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut,
.meta {
  order: 2;
  margin-inline-start: auto;
  padding-inline-start: var(--v4-space-8);
  color: var(--v4-muted);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut {
  display: inline-flex;
  flex: none;
  align-items: center;
}
.meta {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.meta + .shortcut {
  margin-inline-start: 0;
}
.trail {
  order: 3;
  flex: none;
  margin-inline-start: auto;
  color: var(--v4-muted);
}
.label,
.group > [cmdk-group-heading] {
  display: block;
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  color: var(--v4-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-transform: uppercase;
  font-family: var(--v4-type-eyebrow-font-family);
  font-size: var(--v4-type-eyebrow-font-size);
  line-height: var(--v4-type-eyebrow-line-height);
  font-weight: var(--v4-type-eyebrow-font-weight);
  letter-spacing: var(--v4-type-eyebrow-letter-spacing);
}
/* Menu spacing model: the panel pads every side by --v4-menu-pad (p). Rows and rules carry no
   outer margin. A rule is a full-width 1px line drawn p below the previous row and p above the
   next one, so a section's content sits p from the panel edge and from every rule. */
.label:not(:first-child, .separator + *),
:is([role="group"], [cmdk-group]):not(:first-child)
  > :is(.label, [cmdk-group-heading]):first-child {
  position: relative;
  padding-top: calc(var(--v4-space-6) + 2 * var(--v4-menu-pad, var(--v4-space-3)) + var(--v4-size-control-border));
}
.label:not(:first-child, .separator + *),
:is([role="group"], [cmdk-group]):not(:first-child)
  > :is(.label, [cmdk-group-heading]):first-child::before {
  content: "";
  position: absolute;
  inset-inline: calc(-1 * var(--v4-menu-pad, var(--v4-space-3)));
  top: var(--v4-menu-pad, var(--v4-space-3));
  height: var(--v4-size-control-border);
  background-color: var(--v4-line-soft);
}
.separator {
  position: relative;
  flex: none;
  height: calc(2 * var(--v4-menu-pad, var(--v4-space-3)) + var(--v4-size-control-border));
  border: 0;
}
.separator::before {
  content: "";
  position: absolute;
  inset-inline: calc(-1 * var(--v4-menu-pad, var(--v4-space-3)));
  top: var(--v4-menu-pad, var(--v4-space-3));
  height: var(--v4-size-control-border);
  background-color: var(--v4-line-soft);
}
.empty {
  padding: var(--v4-space-16) var(--v4-space-8);
  color: var(--v4-muted);
  text-align: center;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--v4-space-4);
  padding: var(--v4-space-4);
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.hints {
  container-type: inline-size;
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-size-control-lg);
  padding: 0 var(--v4-space-12);
  background-color: var(--v4-tint);
  overflow: hidden;
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.hint {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-4);
}
.hintsExtra {
  min-width: 0;
  margin-inline-start: auto;
  overflow: hidden;
  text-overflow: ellipsis;
}
@container (max-width: 360px) {
  .hint:nth-child(n + 2) {
    display: none;
  }
}
@container (max-width: 200px) {
  .hint {
    display: none;
  }
}
